import { useEffect, useState } from "react"
import Left from'../../shopingcart/src/Left'
import { useParams } from "react-router-dom"


function Adminupdateproduct() {
    const {id}=useParams()
   
    
    const[name,setName]=useState('')
    const[desc,setDesc]=useState('')
    const[mdesc,setMdesc]=useState('')
    const[price,setPrice]=useState('')
    const[qty,setQty]=useState('')
    const[img,setImg]=useState('')
    const[status, setStatus]=useState('')
    const [message,setMessage]=useState('')

    function handleform(e){
        e.preventDefault()
        useEffect(()=>{
            fetch(`/api/singaldata/${id}`).then((resp)=>{ return resp.json()}).then((data)=>{
                console.log(data)
                if(data.status===200){
                setName(data.apiData.name)
                setDesc(data.apiData.desc)
                setMdesc(data.apiData.mdesc)
                setPrice(data.apiData.price)
                setQty(data.apiData.quantity)
                setStock(data.apiData.status)
                setImg(data.apiData.img)
                
                }else{
                    setMessage(data.message)
                }
            })
        },[])
        console.log(desc)
    //     let data=new FormData()
    //    data.append('name',name)
    //    data.append('desc',desc)
    //    data.append('mdesc',mdesc)
    //    data.append('price',price)
    //    data.append('qty',qty)
    //    data.append('img',img)
    //    data.append('status',status)
    //      fetch(`/api/dataupdate/${id}`,{
    //     method:'PUT',
    //    body:data
    // })
    }


    return ( 
        <section>
            
              <div className="container">
            <div className="row">
             <Left/>
                <div className="col-md-8">
         

        <h2> procude data here</h2>
        {message}
        <form onSubmit={(e)=>{handleform(e)}}>
        <label>name</label>
        <input type="text" className="form-control"
       value={name}
       //onChange={(e)=>{setName(e.target.name)}}
        />
        <label>desc</label>
        <textarea className="form-control"
         value={desc}
        onChange={(e)=>{setDesc(e.target.desc)}}
        ></textarea>
        <label>mdesc</label>
        <textarea className="form-control"
        value={mdesc}
        onChange={(e)=>{setMdesc(e.target.mdesc)}}
        ></textarea>
        <label>price</label>
        <input type="number" className="form-control"
          value={price}
      onChange={(e)=>{setPrice(e.target.price)}}
        />
            <label>qty</label>
    <input type="text" className="form-control"
   value={qty}
   onChange={(e)=>{setQty(e.target.value)}}
    />
    <label> product status</label>
    <select className="form-select">
        value={status}
        <option value="IN STOCK"> IN Stoce</option>
        <option value="OUT STOCK"> OUt Stoce</option>
       
    </select>
    <div><img src={`${"/img"}`}></img></div>
        <label>img</label>
        <input type="file" className="form-control"

          onChange={(e)=>{setImg(e.target.files[0])}}
        
        />
    
    <button type="submit" className="btn btn-info form-control">add</button>
  


        </form>
        </div>
        </div>
        </div>
        </section>
     );
}

export default Adminupdateproduct;
